$filePath = "c:\Users\moham\ABCD\src\data\mockData.js"
$content = Get-Content -Path $filePath -Raw

$newProducts = @"
    {
        id: 114,
        title: "Premium Pastel Arch",
        image: "data:image/webp;base64, ",
        price: 3499,
        originalPrice: 4999,
        discountPercentage: 30
    },
    {
        id: 115,
        title: "Gold & Blue Theme",
        image: "https://th.bing.com/th/id/OIP.UC8ufaJHiQipQr_9J8ZyfgHaE8?w=236&h=180&c=7&r=0&o=7&dpr=1.3&pid=1.7&rm=3",
        price: 3299,
        originalPrice: 4499,
        discountPercentage: 26
    },
    {
        id: 116,
        title: "Elegant Room Setup",
        image: "https://th.bing.com/th/id/OIP.IdYWoBJ1upcSeatxM4btmQHaFj?w=262&h=180&c=7&r=0&o=7&dpr=1.3&pid=1.7&rm=3",
        price: 4299,
        originalPrice: 5999,
        discountPercentage: 28
    }
];
"@

$searchPattern = 'id: 113,[\s\S]*?discountPercentage: 30\s*}\s*];'
$replacement = "id: 113,`n        title: `"Cocomelon Theme Circle Decor`",`n        image: cocomelonDecor,`n        price: 3499,`n        originalPrice: 4999,`n        discountPercentage: 30`n    },`n$newProducts`n];"

if ($content -match [regex]::Escape($searchPattern).Replace('\r\n', '\n').Replace('\r', '\n').Replace('\n', '\r?\n')) {
    $content = $content -replace [regex]::Escape($searchPattern).Replace('\r\n', '\n').Replace('\r', '\n').Replace('\n', '\r?\n'), $replacement
    Set-Content -Path $filePath -Value $content -NoNewline
    Write-Host "Birthday products added successfully."
} else {
    Write-Error "Could not find the insertion point in mockData.js."
}
